  "model": "Qwen3-TTS-12Hz-1.7B-Base",
  "input": {
    "text": "如果这几天都没再发，我原来安排的每周打球计划还能继续吗？",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-3496c04aea804b88",
      "seed": 1267105346,
